import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const scriptDirectory = path.dirname(fileURLToPath(import.meta.url));
const projectDirectory = path.resolve(scriptDirectory, "..");
const migrationDirectory = path.join(projectDirectory, "supabase");
const outputPath = path.join(migrationDirectory, "board-all-in-one.sql");
const migrations = [
  "migration-51-board.sql",
  "migration-52-board-views.sql",
  "migration-53-board-reports.sql",
  "migration-54-board-author-actions.sql",
  "migration-55-board-community-complete.sql",
];

function withoutStandaloneTransaction(source, fileName) {
  const begins = source.match(/^begin;\s*$/gim) ?? [];
  const commits = source.match(/^commit;\s*$/gim) ?? [];
  if (begins.length !== 1 || commits.length !== 1) {
    throw new Error(`${fileName} must contain exactly one standalone begin/commit pair.`);
  }

  return source
    .replace(/^begin;\s*$/im, "")
    .replace(/^commit;\s*$/im, "")
    .trim();
}

const sections = [];
for (const fileName of migrations) {
  const source = await readFile(path.join(migrationDirectory, fileName), "utf8");
  sections.push(
    `-- ============================================================================\n` +
      `-- ${fileName}\n` +
      `-- ============================================================================\n\n` +
      withoutStandaloneTransaction(source, fileName),
  );
}

const output = `-- FEATABLE board all-in-one SQL (migrations 51-55)
-- Generated by scripts/build-board-sql-bundle.mjs. Do not edit this file by hand.
-- Requires the existing Featable schema through migration 50, including notifications.
-- Paste this entire file into the Supabase SQL Editor and run it once.
-- The bundle is idempotent and atomic: any failure rolls back the whole board update.

begin;

${sections.join("\n\n")}

commit;
`;

await writeFile(outputPath, output, "utf8");
console.log(`Generated ${path.relative(projectDirectory, outputPath)} from ${migrations.length} migrations.`);
